contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        uint beforeCBalance = address(c).balance;
        uint beforeRBalance = receiver.balance;

        c.sendTo(receiver, amount); if (__ESBMC_reverted()) return;

        uint afterCBalance = address(c).balance;
        uint afterRBalance = receiver.balance;

        assert(afterCBalance == beforeCBalance - amount && afterRBalance == beforeRBalance + amount);
    }

    receive() external payable {}
}

